package parser

import (
	"os"
	"path/filepath"
	"testing"
)

// perfCorpusDir is the committed synthetic corpus (100 files / 5,000
// functions) generated by testdata/perf/gen_codebase.go. Benchmarks read it
// rather than generating a fresh tree so a baseline is comparable across runs.
func perfCorpusDir() string {
	return filepath.Join("..", "..", "testdata", "perf", "large_codebase")
}

func perfCorpusSources(b *testing.B) ([]string, [][]byte) {
	b.Helper()
	entries, err := os.ReadDir(perfCorpusDir())
	if err != nil {
		b.Fatalf("read perf corpus: %v", err)
	}
	var names []string
	var sources [][]byte
	for _, entry := range entries {
		if filepath.Ext(entry.Name()) != ".c" {
			continue
		}
		path := filepath.Join(perfCorpusDir(), entry.Name())
		src, err := os.ReadFile(path)
		if err != nil {
			b.Fatalf("read %s: %v", path, err)
		}
		names = append(names, path)
		sources = append(sources, src)
	}
	if len(names) == 0 {
		b.Fatalf("perf corpus %s has no .c files", perfCorpusDir())
	}
	return names, sources
}

// BenchmarkParseCorpus measures a cold tree-sitter parse of every corpus file.
// Source bytes are preloaded so the number is parser cost, not file I/O.
func BenchmarkParseCorpus(b *testing.B) {
	names, sources := perfCorpusSources(b)
	p := NewParser()
	defer p.CloseAll()
	b.ReportAllocs()
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		for j, src := range sources {
			tree, err := p.Parse(src, names[j])
			if err != nil {
				b.Fatalf("parse %s: %v", names[j], err)
			}
			tree.Close()
		}
	}
}

// BenchmarkParseCachedCorpus measures the steady-state parse-cache hit path
// every detector and graph builder takes once the first pass has populated the
// per-file tree cache.
func BenchmarkParseCachedCorpus(b *testing.B) {
	names, sources := perfCorpusSources(b)
	p := NewParser()
	p.SetMaxCachedTrees(4000)
	defer p.CloseAll()
	for j, src := range sources {
		tree, err := p.ParseCached(src, names[j])
		if err != nil {
			b.Fatalf("prime parse cache %s: %v", names[j], err)
		}
		tree.Release()
	}
	b.ReportAllocs()
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		for j, src := range sources {
			tree, err := p.ParseCached(src, names[j])
			if err != nil {
				b.Fatalf("parse cached %s: %v", names[j], err)
			}
			tree.Release()
		}
	}
}
